import * as fs from 'node:fs'
import type { Telemetry, TelemetryProperties } from '../types'

/**
 * Telemetry client that appends JSON-encoded events to a file for local inspection.
 *
 * Useful for smoke tests and CI validation where you want to verify the events
 * that would be sent to PostHog without actually making network calls.
 */
export class JsonFileTelemetry implements Telemetry {
    private readonly filePath: string

    constructor(filePath: string) {
        this.filePath = filePath
    }

    capture(event: string, properties?: TelemetryProperties): void {
        this.append({ event, properties })
    }

    captureError(event: string, error: unknown, properties?: TelemetryProperties): void {
        this.append({
            event,
            error: error instanceof Error ? error.message : String(error),
            properties,
        })
    }

    async flush(): Promise<void> {}

    async shutdown(): Promise<void> {}

    private append(record: unknown): void {
        try {
            fs.appendFileSync(this.filePath, `${JSON.stringify(record)}\n`)
        } catch {
            // Best-effort: if the file cannot be written, do not block the build.
        }
    }
}
